/** One lightweight, seamless texture shared by the terrain painter and
 * both editors' brush previews. Generated by script/generate-park-water-texture.ts.
 */
export const PARK_WATER_BASE = "#074653";
export const PARK_WATER_TEXTURE_URL = "/park-water-surface.webp";

let texture: HTMLImageElement | undefined;
/** Load once on demand; no extra image request for each stamp or raster. */
export function parkWaterImage(): HTMLImageElement {
  if (!texture) {
    texture = new Image();
    texture.src = PARK_WATER_TEXTURE_URL;
  }
  return texture;
}
